import { expect } from '@wdio/globals';
import { byTextContains, byTextMatches } from '../../helpers/ui.ts';
import { openSection, setBody, recordingSummary, qaMarker } from '../_lib/admin.ts';
import { approvedCount, ADM_DELETE } from '../_lib/app-2110.ts';
import { playerButton, recordingLine, shown, skipWith } from '../_lib/app-0710.ts';
import { nodes } from '../_lib/readiness-1910.ts';
import {
  REC_APPROVER, REC_APPROVED_LINE, ADM_STALE_ERROR,
  requireClientLogin, openRecAdminPrayer, hasSectionRow, approveQaRecording, openUserRecPage, toPlayer, expectNoRecordingForUser, saveShot,
} from '../_lib/app-2510.ts';
import {
  DEL_BODY, MARKED_FULL, MARKED_DRAFT, USER_REC_PREFIX, REC_NOT_MATCHING_FULL, EDIT_SUFFIX,
  delTitle, addQaSegment, uploadK4, openDeleteDialog, dialogButton, deleteOutcome, approveChange, publishText,
  historyHasDeletion, cleanupDelSegment,
} from '../_lib/app-2610.ts';

type Summary = Awaited<ReturnType<typeof recordingSummary>>;

/** Исходное состояние: счётчик админки, сводка записей, страниц у пользователя. Остаток прошлого прогона — ошибка. */
async function baseline(title: string) {
  await openRecAdminPrayer('исходно');
  const count = await approvedCount();
  const summary = await recordingSummary();
  await openRecAdminPrayer('исходно: список');
  if (await hasSectionRow(title)) throw new Error(`«${title}» уже есть (остаток прошлого прогона) — убрать вручную перед тестом`);
  const [, userTotal] = await openUserRecPage(1);
  return { count, summary, userTotal };
}

/** «מחיקת הקטע» → окно → «מחיקת הקטע» из окна → пометка без «הפעולה לא בוצעה…». */
async function markForDelete(title: string, shot: string) {
  await openDeleteDialog(title);
  await (await dialogButton('למחוק את הקטע', ADM_DELETE)).click();
  const outcome = await deleteOutcome();
  await saveShot(shot);
  if (outcome === 'error') throw new Error(`#544d9c вернулся: «${ADM_STALE_ERROR}…» — קטע с записью не помечается к удалению`);
  await expect(byTextContains(MARKED_FULL)).toBeExisting();
  await expect(byTextContains(MARKED_DRAFT)).toBeExisting();
  await expect(byTextContains(ADM_STALE_ERROR)).not.toBeExisting();
}

/** Утверждение удаления + история + итог в админке и у пользователя. place = место QA קטע (последний, M0+1). */
async function approveAndVerify(title: string, b: { count: [number, number]; summary: Summary; userTotal: number }, tag: string) {
  const place = b.userTotal + 1;
  await openRecAdminPrayer(`${tag}: утверждение`);
  await openSection(title);
  await expect(byTextContains(MARKED_FULL)).toBeExisting({ wait: 15000 });   // пометка сохранилась после выхода из экрана
  await approveChange(REC_APPROVER, qaMarker(`${tag}-del`));
  // История: «<title>: הקטע נמחק ממקום N, אושר על ידי בודק QA, …» (544d9c-2610-history.png).
  const line = await historyHasDeletion(title, place, REC_APPROVER);
  expect(line).not.toBe('');
  await saveShot(`${tag}-history.png`);
  // Админка: QA קטע нет, счётчик и сводка записей как в начале (26.10: 1 קטע, «בלי הקראה: 1»).
  await openRecAdminPrayer(`${tag}: итог`);
  expect(await hasSectionRow(title)).toBe(false);
  expect(await approvedCount()).toEqual(b.count);
  const s = await recordingSummary();
  expect(s).toEqual(b.summary);
  // Пользователь: страниц как в начале («1 מתוך 1»), на стр. 1 записи нет — удалённая запись не «переехала» (F-92 AC3, F-91 AC4).
  const [n, m] = await openUserRecPage(1);
  expect([n, m]).toEqual([1, b.userTotal]);
  await expectNoRecordingForUser();
  await saveShot(`${tag}-user-final.png`);
}

describe('26.10 — удаление קטע с записью вместе с записью (#544d9c)', () => {
  const titles: string[] = [];
  let base: { count: [number, number]; summary: Summary; userTotal: number } | null = null;

  after(async function () {
    this.timeout(1800000);
    for (const t of titles) {
      try {
        const r = await cleanupDelSegment(t, REC_APPROVER, qaMarker('Q18-cleanup'));
        if (base && (r.count[1] !== base.count[1] || r.summary.none !== base.summary.none)) {
          console.warn(`[Q-18] после уборки «${t}»: ${r.count.join('/')} קטעים, «בלי הקראה: ${r.summary.none}» ≠ исходно ${base.count.join('/')}, ${base.summary.none} — проверить вручную`);
        }
      } catch (e) {
        console.warn(`[Q-18] УБОРКА НЕ ЗАВЕРШЕНА: удалить вручную «${t}» («מחיקת הקטע» → «אישור ופרסום השינוי»)`, e);
      }
    }
  });

  it('Q-18a קטע с утверждённой записью: «ביטול» ничего не удаляет → «מחיקת הקטע» → «הקטע מסומן למחיקה. עד האישור המשתמשים עדיין רואים אותו.» (без «הפעולה לא בוצעה») → у пользователя «2 מתוך 2» + «הקראה: בודק QA · …» → «אישור ופרסום השינוי» → история «הקטע נמחק ממקום 2» → «1 מתוך 1», запись не перешла #544d9c #1c5b7fc0 #6bddd9 F-102 AC1 AC4 AC5 F-92 AC3 @admin @data @manual-check', async function () {
    this.timeout(3600000);
    await requireClientLogin(this);
    const TITLE = delTitle('עם הקראה');
    base = await baseline(TITLE);

    // 1. Свой QA קטע (mkseg.sh): «+ הוספת קטע כאן» → заголовок, «קטע בדיקה למחיקה עם הקראה», «שם המאשר» → «אישור ופרסום» → «אישור».
    await openRecAdminPrayer('Q-18a: создание');
    titles.push(TITLE);
    await addQaSegment(TITLE, DEL_BODY, REC_APPROVER, qaMarker('Q18a-add'));

    // 2. MP3 «arvit-ashk-k4» → «ממתינה לאישור» → «אישור ההקראה ופרסומה».
    await openRecAdminPrayer('Q-18a: запись');
    await openSection(TITLE);
    if (!(await uploadK4(REC_APPROVER))) skipWith(this, 'на телефоне нет файла «arvit-ashk-k4» в «Файлы → Недавние» (копия .qa/research/rec-pages/arvit-ashk-k4.mp3)');
    await approveQaRecording();

    // 3. «מחיקת הקטע» → окно → «ביטול» (из окна): пометки нет, запись утверждена, кнопка удаления на месте (#6bddd9 п.3).
    await openDeleteDialog(TITLE);
    await saveShot('Q-18a-confirm.png');
    await (await dialogButton('למחוק את הקטע', 'ביטול')).click();
    await expect(byTextContains('למחוק את הקטע')).not.toBeExisting({ wait: 10000 });
    expect(await shown(byTextContains(MARKED_FULL))).toBe(false);
    await expect(byTextMatches(REC_APPROVED_LINE)).toBeExisting();

    // 4. «מחיקת הקטע» → «מחיקת הקטע» в окне → пометка, ошибки нет — запись перед этим НЕ снимали.
    await markForDelete(TITLE, 'Q-18a-marked.png');

    // 5. До утверждения пользователь видит קטע и его запись: «2 מתוך 2», «הקראה: בודק QA · …», «השמע» активна (F-102 AC1, F-91 AC1).
    const page = base.userTotal + 1;
    expect(await openUserRecPage(page)).toEqual([page, page]);
    await toPlayer();
    await expect(recordingLine()).toBeExisting({ wait: 15000 });
    expect((await nodes()).some((n) => n.label.startsWith(USER_REC_PREFIX(REC_APPROVER)))).toBe(true);
    await expect(await playerButton('השמע')).toBeEnabled();
    await saveShot('Q-18a-user-before-approve.png');

    // 6–8. «אישור ופרסום השינוי» → история → итог.
    await approveAndVerify(TITLE, base, 'Q-18a');
    titles.splice(titles.indexOf(TITLE), 1);
  });

  it('Q-18b קטע с записью «לא תואמת» (запись утверждена → правка текста + «אישור ופרסום» → «לא תואמת את הטקסט הנוכחי…») → «מחיקת הקטע» → пометка без «הפעולה לא בוצעה» → «אישור ופרסום השינוי» → история, «1 מתוך 1», запись не перешла #544d9c #1c5b7fc0 F-92 AC2 AC3 F-102 AC4 @admin @data @manual-check', async function () {
    this.timeout(3600000);
    await requireClientLogin(this);
    const TITLE = delTitle('לא תואמת');
    base = await baseline(TITLE);

    await openRecAdminPrayer('Q-18b: создание');
    titles.push(TITLE);
    await addQaSegment(TITLE, DEL_BODY, REC_APPROVER, qaMarker('Q18b-add'));
    await openRecAdminPrayer('Q-18b: запись');
    await openSection(TITLE);
    if (!(await uploadK4(REC_APPROVER))) skipWith(this, 'на телефоне нет файла «arvit-ashk-k4» в «Файлы → Недавние»');
    await approveQaRecording();

    // Правка текста + «אישור ופרסום» → запись «לא תואמת» (сводка «לא תואמות לטקסט» +1).
    await setBody(DEL_BODY + EDIT_SUFFIX);
    await publishText(REC_APPROVER, qaMarker('Q18b-edit'));
    await openRecAdminPrayer('Q-18b: לא תואמת');
    expect((await recordingSummary()).notMatching).toBe(base.summary.notMatching + 1);
    await openRecAdminPrayer('Q-18b: קטע');
    await openSection(TITLE);
    await expect(byTextContains(REC_NOT_MATCHING_FULL)).toBeExisting({ wait: 15000 });
    await saveShot('Q-18b-lo-toemet.png');

    // Удаление прямо с записью «לא תואמת».
    await markForDelete(TITLE, 'Q-18b-marked.png');

    // До утверждения пользователь видит קטע (новый текст), записи «לא תואמת» не предлагается (F-92 AC2).
    const page = base.userTotal + 1;
    expect(await openUserRecPage(page)).toEqual([page, page]);
    expect((await nodes()).some((n) => n.label.includes(EDIT_SUFFIX.trim()))).toBe(true);
    await expectNoRecordingForUser();

    await approveAndVerify(TITLE, base, 'Q-18b');
    titles.splice(titles.indexOf(TITLE), 1);
  });
});
